"""Portable fighter policies (generated by gen_portable.py -- do not edit by hand).

Profiles (build(name)):
  base        frozen repair_guide pursuit, no shield
  base_t3     frozen pursuit + collision shield v3        (= local arm base_t3)
  tuned       ES-tuned pursuit constants + shield v3      (= local arm tuned)
  tuned2      round-2 ES-tuned constants (+ turn_cap_deg / turn_cap) + shield v3  (= local arm tuned2)
  tuned2w[:cap]  tuned2 with the final bank clip widened from 72 to <cap> deg (default 80)  (= local arm tuned2w:<cap>, wide_pilot.py)
  tuned2f     tuned2 + close-range lift-vector finisher (fin_finisher.py + fin_core.py, generated from finisher.py / dcsvet_core.py)  (= local arm tuned2f:<F4>)
  tuned2fr    tuned2f + finisher ground recovery v2 (corner-speed G, idle when fast and diving)  (= local arm tuned2f:<F4>:rec_v2=1, "F4R")
  tuned2t     T17: tune4 run tune04_fin12d gen 17 (finisher constants + bank cap ~74.4, rec_v2, floor 817 m)  (= local arm fin4:runs/tune04_fin12d)
  dcsv2frs[:w] dcsv2fr + collision shield on the far-range net, weights bc_v2b_all (= local arm dcsv2frs:runs/bc_v2b_all.npz)
  dcsv2fr     DCS-imitation intent net (far range, fin_v2.py + bc_v2_intent.npz) + finisher F4R  (= local arm dcsv2fr:runs/bc_v2_intent.npz)
  tuned_open[:secs]  tuned, but when the enemy starts on our LEFT (blue_az < 0) fly BREAK_OUT for the first <secs> s
  fly_feat    option tactician (raw-feature read-out, 54x7 weights, numpy only) on top of base_t3; implemented in flyopt.py (portable/gen_flyopt.py)
Uses only numpy and the official package modules (controller.RepairController, combat_v3.*).
"""
import json, math, sys
from pathlib import Path
import numpy as np
_BASE = Path(__file__).resolve().parent
if str(_BASE) not in sys.path:
    sys.path.insert(0, str(_BASE))
from combat_v3.interface import validate_observation, geometry_from_observation
from combat_v3.controller import wrap_deg
from controller import RepairController


def _load_settings():
    p = _BASE / 'combat_v3' / 'config.json'
    if not p.exists():
        import combat_v3
        p = Path(combat_v3.__file__).resolve().parent / 'config.json'
    return json.loads(p.read_text(encoding='utf-8'))


SETTINGS = _load_settings()

PURSUE, LEAD, LAG, BREAK_IN, BREAK_OUT, HIGH_YOYO, LOW_YOYO, EXTEND, STRAIGHT = range(9)
N_TACTICS = 8          # tactics the brain may choose (STRAIGHT is for scripted opponents only)
NAMES = ['pursue', 'lead', 'lag', 'break_in', 'break_out', 'high_yoyo', 'low_yoyo', 'extend', 'straight']


class TacticalPilot(RepairController):
    def __init__(self, settings=None, variant='tactical'):
        super().__init__(settings or SETTINGS, variant)
        self.tactic = PURSUE
        self.hold_altitude_m = None

    def set_tactic(self, tactic):
        self.tactic = int(tactic)

    def act(self, observation, residual=None, started=True):
        if not started:
            return np.array([0., 0., 0., .8]), False
        o = validate_observation(observation)
        tac = self.tactic
        geo = geometry_from_observation(o)
        d = geo['distance_m']
        near = d < 1100
        self.mode = 'track' if near else 'intercept'
        bearing = geo['bearing_deg']
        heading_error = wrap_deg(bearing - o[5])
        if tac == LEAD:
            lead_delta = wrap_deg(geo['lead_bearing_deg'] - bearing)
            bearing += float(np.clip(lead_delta, -30, 30)) * .8
            heading_error = wrap_deg(bearing - o[5])
        elif tac == LAG:
            if abs(heading_error) < 60:
                lead_delta = wrap_deg(geo['lead_bearing_deg'] - bearing)
                bearing -= float(np.clip(lead_delta, -25, 25)) * .6
                heading_error = wrap_deg(bearing - o[5])
        elif not near and abs(heading_error) < 35:
            lead_delta = wrap_deg(geo['lead_bearing_deg'] - bearing)
            bearing += float(np.clip(lead_delta, -20, 20)) * .35
            heading_error = wrap_deg(bearing - o[5])
        if self.previous_bearing is None:
            self.bearing_rate = 0.
        else:
            rate = np.clip(wrap_deg(bearing - self.previous_bearing) * 60, -15, 15)
            self.bearing_rate = .9 * self.bearing_rate + .1 * rate
        self.previous_bearing = bearing
        feedforward = math.degrees(math.atan(geo['own_tas_mps'] * math.radians(self.bearing_rate) / 9.80665))
        bank = float(np.clip(1.8 * heading_error + feedforward, -72, 72))
        altitude, enemy_altitude = o[2] * .3048, o[22] * .3048
        downward = o[8] * .3048
        if near and geo['blue_angle_deg'] < 45:
            lat = math.radians(o[0]); lat2 = math.radians(o[20])
            rel = np.array([(lat2 - lat) * 6378137, math.radians(o[21] - o[1]) * 6378137 * math.cos((lat + lat2) / 2), -(o[22] - o[2]) * .3048])
            velocity = (o[23:26] - o[6:9]) * .3048
            horizontal = max(float(np.linalg.norm(rel[:2])), 1.)
            horizontal_rate = float(np.dot(rel[:2], velocity[:2])) / horizontal
            elevation_rate = math.degrees((-horizontal * velocity[2] + rel[2] * horizontal_rate) / max(d * d, 1.))
            pitch = geo['elevation_deg'] + float(np.clip(.5 * elevation_rate, -4, 4))
        else:
            gamma = np.clip((enemy_altitude - altitude) * .012 + downward * .16, -8, 12)
            pitch = o[18] + gamma
        desired_close = float(np.clip((d - 600) * .07, -30, 65))
        speed = geo['enemy_equivalent_cas_kts'] + desired_close * 1.9438444924 * geo['cas_ratio']
        if abs(heading_error) > 45:
            speed = min(speed, 290.)
        speed = float(np.clip(speed, 260, 450))
        rudder = 0.
        # ---- tactic-specific target changes (PURSUE leaves everything untouched) ----
        bank_limit = 72.
        if tac == LEAD:
            bank = float(np.clip(1.8 * heading_error + feedforward, -80, 80)); bank_limit = 80.
        elif tac in (BREAK_IN, BREAK_OUT):
            sign = 1. if heading_error >= 0 else -1.
            if tac == BREAK_OUT:
                sign = -sign
            bank = 78. * sign; bank_limit = 80.
            pitch = o[4] + 3.
            speed = 420.
        elif tac == HIGH_YOYO:
            bank *= .6
            pitch += 10.
            speed = min(speed, 300.)
        elif tac == LOW_YOYO:
            pitch -= 8.
            speed = 450.
        elif tac == EXTEND:
            bank = 0.
            pitch = o[18]
            speed = 450.
        elif tac == STRAIGHT:
            if self.hold_altitude_m is None:
                self.hold_altitude_m = altitude
            bank = 0.
            pitch = o[18] + float(np.clip((self.hold_altitude_m - altitude) * .012 + downward * .16, -8, 12))
            speed = 340.
        return self.command(o, float(np.clip(bank, -bank_limit, bank_limit)), float(np.clip(pitch, -18, 25)),
                            float(np.clip(speed, 260, 450)), rudder)


FT = .3048
R_E = 6378137.0
G0 = 9.80665
KT = .514444


def frame(o):
    """Enemy position relative to own (north, east, DOWN) in m, own and enemy NED velocity in m/s."""
    lat, lat2 = math.radians(o[0]), math.radians(o[20])
    rel = np.array([(lat2 - lat) * R_E, math.radians(o[21] - o[1]) * R_E * math.cos((lat + lat2) / 2), -(o[22] - o[2]) * FT])
    return rel, o[6:9] * FT, o[23:26] * FT


# ----------------------------------------------------------------------------------------- shield
DEFAULT_SHIELD = dict(tcpa_s=2.0, miss_m=100., range_m=1500., min_dive_agl_m=3500.)


def shield_targets(o, roll_t, pitch_t, speed_t, cfg):
    rel, ov, ev = frame(o)
    d = float(np.linalg.norm(rel))
    if d > cfg['range_m']:
        return roll_t, pitch_t, speed_t, False
    vrel = ev - ov
    vv = float(np.dot(vrel, vrel))
    if vv < 1.:
        return roll_t, pitch_t, speed_t, False
    tcpa = -float(np.dot(rel, vrel)) / vv
    if tcpa <= 0. or tcpa > cfg['tcpa_s']:
        return roll_t, pitch_t, speed_t, False
    cpa = rel + vrel * tcpa
    if float(np.linalg.norm(cpa)) > cfg['miss_m']:
        return roll_t, pitch_t, speed_t, False
    dive = cpa[2] < -3. and o[2] * FT > cfg['min_dive_agl_m']      # enemy will pass above us -> go down
    pitch = o[4] + (-15. if dive else 15.)
    return 0., float(np.clip(pitch, -25., 40.)), 450., True


class ShieldMixin:
    shield_cfg = None
    shield_ticks = 0

    def enable_shield(self, cfg=None):
        self.shield_cfg = dict(DEFAULT_SHIELD, **(cfg or {}))

    def command(self, obs, roll_target, pitch_target, speed_target, rudder=0., safety=True):
        if self.shield_cfg is not None:
            o = validate_observation(obs)
            roll_target, pitch_target, speed_target, hit = shield_targets(o, roll_target, pitch_target, speed_target, self.shield_cfg)
            if hit:
                self.shield_ticks += 1
                rudder = 0.
        return super().command(obs, roll_target, pitch_target, speed_target, rudder, safety)


class ShieldedTacticalPilot(ShieldMixin, TacticalPilot):
    def __init__(self, shield=True):
        super().__init__()
        if shield:
            self.enable_shield()



PARAM_SPEC = {   # name: (default, low, high)  -- defaults reproduce the frozen PURSUE exactly
    'kp_head': (1.8, 1.0, 3.0),
    'bank_lim': (72., 60., 82.),
    'hold_m': (600., 250., 800.),
    'close_gain': (.07, .03, .15),
    'lead_blend': (.35, 0., .8),
    'near_m': (1100., 700., 1600.),
    'elev_rate_gain': (.5, 0., 1.2),
    'ff_gain': (1., 0., 1.5),
}
PARAM_DEFAULT = {k: v[0] for k, v in PARAM_SPEC.items()}


class ParamPilot(ShieldMixin, TacticalPilot):
    """Frozen PURSUE law with its main constants exposed (defaults == RepairController.act, bit-exact)."""
    def __init__(self, params=None, shield=None):
        super().__init__()
        self.p = dict(PARAM_DEFAULT, **(params or {}))
        if shield:
            self.enable_shield(shield if isinstance(shield, dict) else None)

    def act(self, observation, residual=None, started=True):
        if not started:
            return np.array([0., 0., 0., .8]), False
        P = self.p
        o = validate_observation(observation)
        geo = geometry_from_observation(o)
        d = geo['distance_m']
        near = d < P['near_m']
        self.mode = 'track' if near else 'intercept'
        bearing = geo['bearing_deg']
        heading_error = wrap_deg(bearing - o[5])
        if not near and abs(heading_error) < 35:
            lead_delta = wrap_deg(geo['lead_bearing_deg'] - bearing)
            bearing += float(np.clip(lead_delta, -20, 20)) * P['lead_blend']
            heading_error = wrap_deg(bearing - o[5])
        if self.previous_bearing is None:
            self.bearing_rate = 0.
        else:
            rate = np.clip(wrap_deg(bearing - self.previous_bearing) * 60, -15, 15)
            self.bearing_rate = .9 * self.bearing_rate + .1 * rate
        self.previous_bearing = bearing
        feedforward = P['ff_gain'] * math.degrees(math.atan(geo['own_tas_mps'] * math.radians(self.bearing_rate) / 9.80665))
        bank = float(np.clip(P['kp_head'] * heading_error + feedforward, -P['bank_lim'], P['bank_lim']))
        altitude, enemy_altitude = o[2] * FT, o[22] * FT
        downward = o[8] * FT
        if near and geo['blue_angle_deg'] < 45:
            lat = math.radians(o[0]); lat2 = math.radians(o[20])
            rel = np.array([(lat2 - lat) * 6378137, math.radians(o[21] - o[1]) * 6378137 * math.cos((lat + lat2) / 2), -(o[22] - o[2]) * .3048])
            velocity = (o[23:26] - o[6:9]) * .3048
            horizontal = max(float(np.linalg.norm(rel[:2])), 1.)
            horizontal_rate = float(np.dot(rel[:2], velocity[:2])) / horizontal
            elevation_rate = math.degrees((-horizontal * velocity[2] + rel[2] * horizontal_rate) / max(d * d, 1.))
            pitch = geo['elevation_deg'] + float(np.clip(P['elev_rate_gain'] * elevation_rate, -4, 4))
        else:
            gamma = np.clip((enemy_altitude - altitude) * .012 + downward * .16, -8, 12)
            pitch = o[18] + gamma
        desired_close = float(np.clip((d - P['hold_m']) * P['close_gain'], -30, 65))
        speed = geo['enemy_equivalent_cas_kts'] + desired_close * 1.9438444924 * geo['cas_ratio']
        if abs(heading_error) > P.get('turn_cap_deg', 45.):
            speed = min(speed, P.get('turn_cap', 290.))
        speed = float(np.clip(speed, 260, 450))
        cap = float(P.get('bank_cap', 72.))   # 72 unless a profile widens it (tuned2w)
        return self.command(o, float(np.clip(bank, -cap, cap)), float(np.clip(pitch, -18, 25)), speed, 0.)



class OpenPilot(ParamPilot):
    def __init__(self, params=None, shield=None, tactic=BREAK_OUT, secs=6., only_side=0):
        super().__init__(params, shield)
        self.o_tactic, self.o_ticks, self.only_side = tactic, int(secs * 60), int(only_side)
        self.k = 0
        self.side = None
        self.n_def_ticks = 0

    def act(self, observation, residual=None, started=True):
        if not started:
            return np.array([0., 0., 0., .8]), False
        self.k += 1
        if self.side is None:
            geo = geometry_from_observation(validate_observation(observation))
            self.side = 1 if geo['blue_az_deg'] >= 0 else -1
        if self.k <= self.o_ticks and self.o_tactic != PURSUE and (self.only_side == 0 or self.side == self.only_side):
            self.n_def_ticks += 1
            TacticalPilot.set_tactic(self, self.o_tactic)
            return TacticalPilot.act(self, observation)
        return super().act(observation)




# ----------------------------------------------------------------------------------------- profiles
TIGHT3 = dict(tcpa_s=2.0, miss_m=60., range_m=1000.)
TUNED = {"kp_head": 2.1047394901637024, "bank_lim": 72.22805324866029, "hold_m": 683.0684541552596, "close_gain": 0.08832200094446549, "lead_blend": 0.5782281696598863, "near_m": 1135.4293314199383, "elev_rate_gain": 0.45344146668067126, "ff_gain": 1.2286144927801426}
TUNED2 = {"kp_head": 2.5043240748028532, "bank_lim": 75.14197420266456, "hold_m": 715.3569245383599, "close_gain": 0.0908981225379508, "lead_blend": 0.621943273035301, "near_m": 1061.2404759048363, "elev_rate_gain": 0.5593290184172319, "ff_gain": 1.0072528098477374, "turn_cap_deg": 47.08463902035993, "turn_cap": 267.2075878629207}
OPEN_TACTIC = BREAK_OUT
FIN_F4 = dict(aa_max=180., enter_deg=180., exit_deg=180., enter_m=3000., exit_m=3500., turn_cas=340., n_cap=8., merge_off_m=400.)
FIN_F4R = dict(FIN_F4, rec_v2=1.)
# T17 = tune4 run tune04_fin12d gen 17 (2026-10-28): finisher constants + base bank cap, rec_v2 on (full precision)
FIN_T17 = dict(FIN_F4, **{'k_ang': 2.7381489569731503, 'k_ff': 0.7948903458313633, 'hold_m': 626.0734638647215, 'turn_cas': 322.8694973689891, 'turn_deg': 22.785508617479728, 'n_cap': 8.512577849891093, 'enter_m': 3017.370554423556, 'merge_off_m': 249.99925456570134, 'floor_m': 817.2447691311949, 'rec_v2': 1.0})
CAP_T17 = 74.3759186171109


def build(name='tuned'):
    base, _, arg = name.partition(':')
    if base == 'base':
        return ShieldedTacticalPilot(shield=False)
    if base == 'base_t3':
        p = ShieldedTacticalPilot(shield=False)
        p.enable_shield(TIGHT3)
        return p
    if base == 'tuned':
        return ParamPilot(dict(TUNED), shield=TIGHT3)
    if base == 'tuned2':
        return ParamPilot(dict(TUNED2), shield=TIGHT3)
    if base == 'tuned2w':
        cap = float(arg or 80)
        return ParamPilot(dict(TUNED2, bank_lim=cap, bank_cap=cap), shield=TIGHT3)
    if base == 'tuned2f':
        import fin_finisher    # portable/fin_finisher.py + fin_core.py (generated together with this file)
        return fin_finisher.FinisherPilot(ParamPilot(dict(TUNED2), shield=TIGHT3), dict(FIN_F4))
    if base == 'tuned2fr':
        import fin_finisher
        return fin_finisher.FinisherPilot(ParamPilot(dict(TUNED2), shield=TIGHT3), dict(FIN_F4R))
    if base == 'tuned2t':
        import fin_finisher
        return fin_finisher.FinisherPilot(ParamPilot(dict(TUNED2, bank_lim=CAP_T17, bank_cap=CAP_T17), shield=TIGHT3), dict(FIN_T17))
    if base == 'dcsv2fr':
        import fin_v2          # portable/fin_v2.py (generated from dcsvet_v2.py) + weights next to it
        return fin_v2.DcsV2Pilot(str(_BASE / ((arg or 'bc_v2_intent') + '.npz')), fin_cfg=dict(FIN_F4R)).fin
    if base == 'dcsv2frs':     # + collision shield for the far-range net (2026-10-28); default weights = v2b (all Ace data)
        import fin_v2
        return fin_v2.DcsV2Pilot(str(_BASE / ((arg or 'bc_v2b_all') + '.npz')), fin_cfg=dict(FIN_F4R, v2_shield=1.)).fin
    if base == 'tuned_open':
        return OpenPilot(dict(TUNED), shield=TIGHT3, tactic=OPEN_TACTIC, secs=float(arg or 6), only_side=-1)
    if base == 'fly_feat':
        import flyopt          # portable/flyopt.py (generated by gen_flyopt.py); only needed for this profile
        return flyopt.build()
    raise ValueError('unknown profile ' + name)
